using System;using System.Text;using UnityEngine;using LWS.TruckSports;using LWS.TruckBowling;
namespace LWS.TruckMusicalParking {
public enum ParkingPhase {Countdown,Music,Scramble,RoundResult,Complete}
public sealed class ParkingMatch:SportsEventSession {
 public SportsEventTruck[] trucks;public ParkingBay[] bays;public SportsEventCamera arenaCamera;public SportsCameraFit framing;public AudioSource music;public TextMesh[] identities;public bool[] active=new bool[8];public int[] secured=new int[8];public float[] capture=new float[8],routeProgress=new float[8],debt=new float[8];public ParkingPhase Phase{get;private set;}public int Round{get;private set;}public int Remaining{get;private set;}public int Winner{get;private set;}=-1;public int Eliminated{get;private set;}=-1;public int TotalCaptures{get;private set;}public float Age{get;private set;}public int Seed{get;private set;}
 float musicDuration;readonly float[] angles=new float[8],lastLegal=new float[8],reaction=new float[8],claimStart=new float[8],distances=new float[8];readonly int[] selected=new int[8];readonly bool[] inside=new bool[8];readonly Vector3[] executionOffset=new Vector3[8];System.Random random;readonly StringBuilder text=new StringBuilder(1200);
 public override string Title=>"TRUCK MUSICAL PARKING";public override int MinimumPlayers=>8;public override int MaximumPlayers=>8;public override bool UsesAction=>false;public override int OptionCount=>1;public override string OptionLabel=>"EIGHT TRUCKS · SEVEN ELIMINATIONS";
 public override string Help=>"WHEN THE MUSIC STOPS, FIND A SPACE\nEight trucks circle the painted outer loop. Up to four humans, independent sources, AI fills. Music lasts an unpredictable5–12s. Red bays are CLOSED. Keep circulating outside them; the horn and green OPEN signs signal the scramble, even with audio muted. AI learns the stop only when you do.\n\nMOVEMENT DRIVES / BRAKES / REVERSES\nPark your WHOLE scoring footprint inside an open bay, under0.9m/s and upright for one continuous second. The progress strip shows capture. Rivals can push you before it locks. A secured truck is protected, earns one space only and cannot be displaced for that round. Exact simultaneous claims use a rotating seeded priority; callback order has no role.\n\nNO CAMPING\nYou need real forward movement on the outer loop, including recent movement outside bays when the horn sounds. Otherwise DRIVE THE LOOP8m before capturing. The HUD warns early; no punitive teleport.\n\nONE ELIMINATION PER ROUND\nWith one fewer space than trucks, the remaining unparked truck is eliminated. After28s, if several remain, eliminate the lowest CURRENT valid capture progress; ties lose by greater distance to a free bay; exact ties use rotating seeded priority. Previously displaced progress is not banked. All other contenders advance, even if timeout leaves several unparked. Seven rounds, one winner. Eliminated humans keep the shared spectator view. Each round resets onto a validated outer grid and rotates the bay arrangement. Rematch retains names/colors/sources/difficulty. Pause/disconnect preserves music position, motion and claims. Offline only.";
 public override string Header=>Title+" | ROUND "+Round+" / 7 | "+Remaining+" TRUCKS · "+Mathf.Max(0,Remaining-1)+" SPACES";
 public override string Status=>Phase==ParkingPhase.Countdown?"READY · "+Mathf.CeilToInt(3-Age):Phase==ParkingPhase.Music?"♫ MUSIC PLAYING · KEEP CIRCLING OUTSIDE THE CLOSED BAYS":Phase==ParkingPhase.Scramble?(Age<1?"HORN!  PARK NOW":"PARK NOW · "+Mathf.Max(0,28-Age).ToString("F0")+"s LEFT"):"ELIMINATED: "+(Eliminated<0?"—":setup.players[Eliminated].name);
 public override string Standings{get{text.Clear();for(int i=0;i<8;i++){text.Append("<color=#").Append(ColorUtility.ToHtmlStringRGB(setup.players[i].color)).Append('>').Append(setup.players[i].name).Append("</color>  ").Append(!active[i]?"OUT":secured[i]>=0?"SECURED":Phase==ParkingPhase.Music?routeProgress[i]<8?"KEEP MOVING":"CIRCLING":debt[i]>0?"LOOP "+debt[i].ToString("F0")+"m":capture[i]>0?"PARK "+Mathf.RoundToInt(capture[i]*100)+"%":"SEEK A BAY").Append(i==7?"":"\n");}return text.ToString();}}public override string Results=>(Winner<0?"NO WINNER":setup.players[Winner].name+" WINS THE LAST SPACE")+"\n\nSeven eliminations · "+TotalCaptures+" physical captures\n\n"+Standings;
 public override bool ValidateSources(out string reason){if(!base.ValidateSources(out reason))return false;int humans=0;for(int i=0;i<8;i++)if(setup.players[i].source!=BowlingSource.AI)humans++;if(humans>4){reason="At most four human sources; AI fills eight competitors.";return false;}return true;}
 protected override void BeginGame(){Seed=UnityEngine.Random.Range(1,100000);random=new System.Random(Seed);Round=0;Remaining=8;Winner=Eliminated=-1;TotalCaptures=0;for(int i=0;i<8;i++)active[i]=true;BeginRound();}
 void BeginRound(){Round++;Age=0;Phase=ParkingPhase.Countdown;music.Stop();musicDuration=5+(float)random.NextDouble()*7;int place=0;for(int i=0;i<8;i++){secured[i]=selected[i]=-1;capture[i]=routeProgress[i]=debt[i]=0;lastLegal[i]=-10;claimStart[i]=float.PositiveInfinity;float angle=place*360f/Remaining;var p=new Vector3(Mathf.Sin(angle*Mathf.Deg2Rad)*30,.55f,Mathf.Cos(angle*Mathf.Deg2Rad)*23);var tangent=new Vector3(Mathf.Cos(angle*Mathf.Deg2Rad)*30,0,-Mathf.Sin(angle*Mathf.Deg2Rad)*23);if(active[i]){trucks[i].visuals.gameObject.SetActive(true);trucks[i].Prepare(p,Quaternion.LookRotation(tangent));trucks[i].Power(false);trucks[i].body.isKinematic=true;place++;}else trucks[i].Park(new Vector3(-46+i*4,.5f,-36));angles[i]=Angle(p);float error=Mathf.Lerp(.6f,.08f,(int)setup.players[i].difficulty*.5f);executionOffset[i]=new Vector3(((float)random.NextDouble()*2-1)*error,0,((float)random.NextDouble()*2-1)*error);reaction[i]=Mathf.Lerp(.75f,.16f,(int)setup.players[i].difficulty*.5f)+(float)random.NextDouble()*.13f;}for(int b=0;b<8;b++){int index=(b+Round-1)%8;float x=(index%4-1.5f)*11,z=index<4?-7:7;bays[b].transform.SetPositionAndRotation(new Vector3(x,.035f,z),Quaternion.Euler(0,index<4?0:180,0));bays[b].ResetBay(b<Remaining-1,false);bays[b].caption.transform.rotation=Quaternion.Euler(90,0,0);}Gate();}
 static float Angle(Vector3 p)=>Mathf.Atan2(p.x/30,p.z/23)*Mathf.Rad2Deg;
 float LoopStep(int i,float dt){var p=trucks[i].body.position;float radius=new Vector2(p.x/30,p.z/23).magnitude;float angle=Angle(p);float delta=Mathf.DeltaAngle(angles[i],angle);angles[i]=angle;float advance=radius>.76f&&radius<1.22f&&delta>0&&delta<30?delta*Mathf.Deg2Rad*26:0;if(advance>.005f){lastLegal[i]=Age;routeProgress[i]+=advance;}return advance;}
 public void Horn(){if(Phase!=ParkingPhase.Music)return;for(int i=0;i<8;i++)if(active[i]){bool inBay=false;foreach(var b in bays)if(b.gameObject.activeSelf&&ParkingRules.Contains(trucks[i].shape,trucks[i].body,b.transform.position,b.transform.rotation,b.size)){inBay=true;break;}debt[i]=routeProgress[i]>=8&&Age-lastLegal[i]<1.2f&&!inBay?0:8;selected[i]=-1;}Phase=ParkingPhase.Scramble;Age=0;music.Stop();foreach(var bay in bays)if(bay.gameObject.activeSelf)bay.SetOpen(true);feedback.Play(2,0,true);}
 Vector2 CircleAI(int i){var t=trucks[i];float theta=Angle(t.body.position)*Mathf.Deg2Rad+.38f;return DriveTo(i,new Vector3(Mathf.Sin(theta)*30,0,Mathf.Cos(theta)*23),10,false);}
 Vector2 DriveTo(int i,Vector3 target,float desired,bool parking){var t=trucks[i];var delta=Vector3.ProjectOnPlane(target-t.body.position,Vector3.up);float angle=Vector3.SignedAngle(Vector3.ProjectOnPlane(t.transform.forward,Vector3.up),delta,Vector3.up);bool reverse=parking&&Mathf.Abs(angle)>112;float along=Vector3.Dot(t.body.linearVelocity,t.transform.forward);float steer=Mathf.Clamp((reverse?Mathf.DeltaAngle(angle,180):angle)/28,-1,1)*(reverse?-1:1);if(Mathf.Abs(angle)>45&&!reverse)desired*=.45f;float throttle=Mathf.Clamp(((reverse?-desired:desired)-along)*.65f,-1,1);return new Vector2(steer,throttle);}
 Vector2 ParkAI(int i){if(Age<reaction[i]||debt[i]>0)return CircleAI(i);var t=trucks[i];int bay=selected[i];if(bay<0||!bays[bay].gameObject.activeSelf||bays[bay].Owner>=0){float best=float.PositiveInfinity;bay=-1;for(int j=0;j<8;j++)if(bays[j].gameObject.activeSelf&&bays[j].Owner<0){float score=Vector3.Distance(t.body.position,bays[j].transform.position)+(i*7+j*11+Seed)%9;for(int k=0;k<8;k++)if(k!=i&&active[k]&&Vector3.Distance(trucks[k].body.position,bays[j].transform.position)<3)score+=9;if(score<best){best=score;bay=j;}}selected[i]=bay;}if(bay<0)return Vector2.zero;float distance=Vector3.ProjectOnPlane(bays[bay].transform.position-t.body.position,Vector3.up).magnitude;if(distance<1.7f&&t.body.linearVelocity.magnitude<1.4f){Brake(i);return Vector2.zero;}return DriveTo(i,bays[bay].transform.position+executionOffset[i],Mathf.Clamp((distance-.7f)*1.5f,0,11),true);}
 void Brake(int i){trucks[i].command=Vector2.zero;foreach(var w in trucks[i].wheels){w.MotorTorque=0;w.BrakeTorque=trucks[i].brakeTorque;w.SteerAngle=0;}}
 protected override void Simulate(float dt){Age+=dt;if(Phase==ParkingPhase.Countdown){if(Age>=3){Age=0;Phase=ParkingPhase.Music;for(int i=0;i<8;i++)if(active[i]){trucks[i].body.isKinematic=false;trucks[i].Power(true);}music.Play();}return;}if(Phase==ParkingPhase.RoundResult){if(Age>=2.5f){if(Remaining==1){Phase=ParkingPhase.Complete;for(int i=0;i<8;i++)if(active[i])Winner=i;EndMatch();}else BeginRound();}return;}if(Phase!=ParkingPhase.Music&&Phase!=ParkingPhase.Scramble)return;
 for(int i=0;i<8;i++)if(active[i]&&secured[i]<0){float advance=LoopStep(i,dt);if(Phase==ParkingPhase.Scramble)debt[i]=Mathf.Max(0,debt[i]-advance);bool bot=setup.players[i].source==BowlingSource.AI;var drive=bot?(Phase==ParkingPhase.Music?CircleAI(i):ParkAI(i)):commands[i];bool hold=bot&&Phase==ParkingPhase.Scramble&&selected[i]>=0&&debt[i]<=0&&Age>=reaction[i]&&Vector3.ProjectOnPlane(bays[selected[i]].transform.position-trucks[i].body.position,Vector3.up).magnitude<1.7f&&trucks[i].body.linearVelocity.magnitude<1.4f;if(hold)Brake(i);else trucks[i].TickDrive(drive);}
 if(Phase==ParkingPhase.Music){if(Age>=musicDuration)Horn();return;}
 for(int i=0;i<8;i++){inside[i]=false;if(!active[i]||secured[i]>=0)continue;int candidate=-1;if(debt[i]<=0&&trucks[i].body.linearVelocity.magnitude<.9f&&Vector3.Dot(trucks[i].transform.up,Vector3.up)>.8f&&trucks[i].body.position.y<2.5f)for(int b=0;b<8;b++)if(bays[b].gameObject.activeSelf&&bays[b].Owner<0&&ParkingRules.Contains(trucks[i].shape,trucks[i].body,bays[b].transform.position,bays[b].transform.rotation,bays[b].size)){candidate=b;break;}if(candidate<0){capture[i]=0;claimStart[i]=float.PositiveInfinity;}else{inside[i]=true;if(float.IsInfinity(claimStart[i]))claimStart[i]=Age;capture[i]=Mathf.Min(1,(Age-claimStart[i])/ParkingRules.CaptureSeconds);selected[i]=candidate;}}
 for(int b=0;b<8;b++)if(bays[b].gameObject.activeSelf&&bays[b].Owner<0){int owner=-1;for(int i=0;i<8;i++)if(active[i]&&secured[i]<0&&inside[i]&&selected[i]==b&&capture[i]>=1&&(owner<0||ParkingRules.BetterClaim(claimStart[i],i,claimStart[owner],owner,(Seed+Round)%8)))owner=i;if(owner>=0)Secure(owner,b);}
 int unparked=0;for(int i=0;i<8;i++)if(active[i]&&secured[i]<0)unparked++;if(unparked==1||Age>=28)Resolve();}
 public bool Secure(int slot,int bay){if(!active[slot]||secured[slot]>=0||bays[bay].Owner>=0)return false;secured[slot]=bay;capture[slot]=1;bays[bay].Secure(slot,setup.players[slot].color,setup.players[slot].name);trucks[slot].Power(false);trucks[slot].body.linearVelocity=trucks[slot].body.angularVelocity=Vector3.zero;trucks[slot].body.isKinematic=true;TotalCaptures++;feedback.Play(3,0,true);Pulse(slot,.15f,.09f);return true;}
 void Resolve(){if(Phase!=ParkingPhase.Scramble)return;for(int i=0;i<8;i++){distances[i]=float.PositiveInfinity;if(active[i]&&secured[i]<0)foreach(var b in bays)if(b.gameObject.activeSelf&&b.Owner<0)distances[i]=Mathf.Min(distances[i],Vector3.ProjectOnPlane(trucks[i].body.position-b.transform.position,Vector3.up).magnitude);}int loser=ParkingRules.Lowest(active,secured,capture,distances,(Seed+Round)%8);if(loser<0)throw new InvalidOperationException("Parking round has no unparked contender");Eliminated=loser;active[loser]=false;Remaining--;Phase=ParkingPhase.RoundResult;Age=0;foreach(var t in trucks)t.Power(false);music.Stop();feedback.Play(4,0,true);Gate();Debug.Log("PARKING_ELIMINATION round="+Round+" loser="+loser+" remaining="+Remaining+" captures="+TotalCaptures);}
 protected override void Present(float dt){if(music!=null)music.volume=Live?settings.music*.35f:0;if(trucks==null)return;for(int i=0;i<8;i++){identities[i].transform.position=trucks[i].body.position+Vector3.up*2.5f;identities[i].text=setup.players[i].name;identities[i].color=active[i]?setup.players[i].color:Color.gray;}}
 protected override void StopGame(){if(music!=null)music.Stop();if(trucks!=null)foreach(var t in trucks)t.Park(t.body.position);}protected override void StopSounds(){if(trucks!=null)foreach(var t in trucks)t.StopSound();}protected override void SetPaused(bool pause){if(music==null)return;if(pause)music.Pause();else if(Phase==ParkingPhase.Music)music.UnPause();}
}
}
